const express = require('express');
const { fork } = require('child_process');
const path = require('path');
const { AuditRun } = require('../models/auditRun');

const app = express();

app.post('/api/crypto/audits/run/:runId', async (req, res) => {
  if (!req.session || !req.session.userId) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  // Enforce institutional auditor role and account ownership
  const audit = await AuditRun.findOne({
    where: {
      id: req.params.runId,
      institutionId: req.session.institutionId
    }
  });

  if (!audit || req.session.role !== 'CERTIFIED_AUDITOR') {
    return res.status(403).json({ error: 'Forbidden: unauthorized access to institutional ledger audit' });
  }

  const workerPath = path.join(__dirname, 'workers', 'cryptoLedgerAudit.js');
  const child = fork(workerPath, [], {
    env: {
      ...process.env,
      AUDIT_RUN_ID: req.params.runId,
      INSTITUTION_ID: req.session.institutionId
    }
  });

  child.on('message', (result) => {
    res.json({
      runId: req.params.runId,
      walletBalances: result.balances,
      coldStorageAudit: result.coldStorageLedger
    });
  });
});

app.listen(7007);
